SELECT p.id, p.title, p.content, p.images, p.status, p.reject_reason AS rejectReason, p.view_count AS viewCount, p.like_count AS likeCount, p.comment_count AS commentCount, DATE_FORMAT(p.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, u.id AS userId, u.nickname AS nickName, u.avatar FROM post p LEFT JOIN user u ON u.id = p.user_id
AND p.status = #{status}
AND p.status != 4 AND p.user_id = #{userId}
AND (p.title LIKE CONCAT('%',#{keyword},'%') OR p.content LIKE CONCAT('%',#{keyword},'%'))
ORDER BY p.create_time DESC

SELECT p.id, p.title, p.content, p.images, p.status, p.reject_reason AS rejectReason, p.view_count AS viewCount, p.like_count AS likeCount, p.comment_count AS commentCount, DATE_FORMAT(p.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, u.id AS userId, u.nickname AS nickName, u.avatar FROM post p LEFT JOIN user u ON u.id = p.user_id
AND (p.status = #{status}
OR (p.user_id = #{currentUserId} AND p.status = 3)
)
AND p.user_id = #{userId}
AND (p.title LIKE CONCAT('%',#{keyword},'%') OR p.content LIKE CONCAT('%',#{keyword},'%'))
ORDER BY p.create_time DESC
